const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '比例尺 1:10000' },
      { kind: 'text', payload: '图上距离 7 厘米' },
      { kind: 'text', payload: '实际距离 70000 厘米' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = W * 0.14;
    var x1 = W * 0.86;
    var y = H * 0.54;
    var tick = Math.min(18, H * 0.06);
    var cmds = [['M', x0, y], ['L', x1, y]];
    for (var i = 0; i <= 7; i++) {
      var x = x0 + (x1 - x0) * i / 7;
      var th = (i === 0 || i === 7) ? tick * 1.25 : tick;
      cmds.push(['M', x, y - th]);
      cmds.push(['L', x, y + th]);
    }
    return {
      schemaVersion: 1,
      sceneId: 'scale-segment',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'segment', commands: cmds }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'segment', fill: '#26354a', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: H * 0.18 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: W / 2, y: y - tick - 20 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: W / 2, y: y + tick + 20 }, hAlign: 'center', vAlign: 'top', color: '#26354a' }
        ]
      }
    };
  }
};
